export type Resource={title:string;url:string;type:'Watch'|'Read'|'Practice';free?:boolean}
export type Lesson={id:string;title:string;tag:string;why:string;learn:string;practice:string;build:string;criteria:string;resources:Resource[]}
export type Stage={id:string;title:string;subtitle:string;lessons:Lesson[]}
const k=(title:string,url:string,type:Resource['type']='Read'):Resource=>({title,url,type,free:true})
export const stages:Stage[]=[
{id:'foundation',title:'01 · The Editor’s Brain',subtitle:'Learn how editing creates meaning before touching effects',lessons:[
{id:'f1',title:'The editor’s job',tag:'Concept',why:'Editors control what the audience sees, hears, feels, and understands.',learn:'Study the difference between assembling footage and shaping a story.',practice:'Step 1: Pick 8-10 unrelated clips. Step 2: Watch them once without editing and write three possible stories. Step 3: Choose one story and write a one-sentence beginning, middle, and end. Step 4: Arrange only the clips that support that story. Step 5: Remove any shot that does not add information or feeling. Output: one 30-45s rough sequence plus the three rejected story ideas. Pass: explain the purpose of every remaining shot in one sentence.',build:'Create a 30-second sequence using only cuts.',criteria:'You can explain why every shot is present.',resources:[k('5 things editors literally do','https://www.youtube.com/watch?v=QqIIHi5F3-o','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'f2',title:'Shot language',tag:'Concept',why:'Shot size, angle, movement, and composition communicate information.',learn:'Learn wide, medium, close-up, inserts, reaction shots, and establishing shots.',practice:'Step 1: Collect 20-30 shots from one film, interview, or vlog. Step 2: Label each as wide, medium, close-up, insert, reaction, or establishing. Step 3: Add a second label for its job: location, information, emotion, action, or reaction. Step 4: Pick one simple action and build a five-shot sequence using different shot sizes. Step 5: Remove any shot that has no clear purpose. Output: shot log + five-shot sequence. Pass: justify each shot by purpose rather than appearance.',build:'Shoot or collect five shot types for one simple action.',criteria:'You can choose a shot because of its purpose, not because it looks cool.',resources:[k('Joel & Ethan Coen — Shot | Reverse Shot','https://www.youtube.com/watch?v=5UE3jz_O_EM','Watch'),k('How to Cut a Film — The Secrets of Editing','https://www.youtube.com/watch?v=ORK8k8_mHyk','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'f3',title:'Why do we cut?',tag:'Concept',why:'A cut should change information, emotion, time, space, or attention.',learn:'Study motivated cuts and invisible vs noticeable editing.',practice:'Step 1: Choose a 30-60s scene with at least 8 cuts. Step 2: Pause just before each cut and predict why the editor cuts there. Step 3: Mark each cut as information, emotion, time, space, movement, sound, or attention. Step 4: Re-edit the scene two ways: invisible continuity and deliberately noticeable cuts. Step 5: Compare what changed for the viewer. Output: two versions + a short cut-by-cut note. Pass: identify a clear reason for every major cut.',build:'Re-edit the same footage two ways: invisible and intentionally noticeable.',criteria:'You can name the reason for a cut.',resources:[k('Cuts & Transitions 101 — RocketJump Film School','https://www.youtube.com/watch?v=OAH0MoAv2CI','Watch'),k('The Kuleshov Effect — Folding Ideas','https://www.youtube.com/watch?v=Vy2Vhnqtu8I','Watch'),k('How to Cut a Film — CineFix','https://www.youtube.com/watch?v=ORK8k8_mHyk','Watch')]},
{id:'f4',title:'Continuity',tag:'Craft',why:'Continuity keeps viewers oriented so story attention is not wasted.',learn:'Learn screen direction, eyelines, match cuts, action continuity, and the 180-degree rule.',practice:'Step 1: Use two people performing a simple action or stage your own. Step 2: Establish screen direction with a master shot. Step 3: Add over-the-shoulder or matching shots while keeping the 180-degree line. Step 4: Match eyelines and movement across cuts. Step 5: Deliberately create one continuity mistake, then fix it. Output: 30-45s dialogue/action scene plus before/after mistake. Pass: a viewer can follow who is where without explanation.',build:'Make a 30-second continuity scene.',criteria:'Your viewer can understand who is where without explanation.',resources:[k('Joel & Ethan Coen — Shot | Reverse Shot','https://www.youtube.com/watch?v=5UE3jz_O_EM','Watch'),k('Continuity Editing — film form lecture','https://www.youtube.com/watch?v=XpRbOToDCU8','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'f5',title:'Pacing and rhythm',tag:'Craft',why:'Pacing is not simply fast cuts; it is the timing of information and emotion.',learn:'Study shot duration, acceleration, deceleration, pauses, and rhythm.',practice:'Step 1: Choose 8-12 clips that can tell one simple event. Step 2: Make a 20s calm version using longer holds and pauses. Step 3: Duplicate it and make an energetic version using shorter shots and movement-based cuts. Step 4: Make a tense version using anticipation, silence, and delayed information. Step 5: Keep the same basic footage and story. Output: three 20-30s edits. Pass: another person can identify the intended mood of each version without being told.',build:'Three 20-second edits from the same footage.',criteria:'The emotional difference is obvious without changing the story.',resources:[k('Why action movies are boring... and spectacular','https://www.youtube.com/watch?v=f4yiwQakF7c','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'f6',title:'Attention',tag:'Psychology',why:'Editing directs the viewer’s eye and predicts what they will notice next.',learn:'Study visual hierarchy, anticipation, contrast, reaction shots, and information withholding.',practice:'Step 1: Pick a 30-45s sequence with several competing visual elements. Step 2: Identify the intended point of attention for each moment. Step 3: Reorder or remove shots so the viewer receives the important information first. Step 4: Use reaction shots, contrast, timing, and pauses to guide attention. Step 5: Show the original and revised versions to someone without explanation. Output: before/after edit + notes on what changed. Pass: the viewer notices the intended subject at the intended moment.',build:'Create a 30-second attention-controlled edit.',criteria:'You can deliberately direct attention with timing and shot choice.',resources:[k('The Science of Film Editing','https://www.youtube.com/watch?v=02JF19lJ29M','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},]},
{id:'story',title:'02 · Storytelling',subtitle:'Turn raw footage into meaning',lessons:[
{id:'s1',title:'Story beats',tag:'Story',why:'A good edit has progression, not just pretty shots.',learn:'Identify setup, escalation, turning point, payoff, and release.',practice:'Step 1: Choose a 60-90s video or scene. Step 2: Write down the setup, escalation, turning point, payoff, and release. Step 3: Reduce those beats to five one-line statements. Step 4: Use your own footage or stock clips to create the same progression in 45-60s. Step 5: Watch once with sound off and once with sound on. Output: beat sheet + 45-60s edit. Pass: a viewer can explain what changed from beginning to end.',build:'Edit a 45-second story with a clear beginning, middle, and end.',criteria:'The viewer can describe what changed.',resources:[k('The Science of Film Editing','https://www.youtube.com/watch?v=02JF19lJ29M','Watch'),k('How to Cut a Film — CineFix','https://www.youtube.com/watch?v=ORK8k8_mHyk','Watch'),k('Story Structure & Pacing','https://www.sabaoon.dev/courses/video-editing-techniques/01-story-structure-pacing','Read')]},
{id:'s2',title:'Motivated cuts',tag:'Craft',why:'Cuts feel natural when they are motivated by story, movement, sound, or attention.',learn:'Learn movement matches, gaze matches, sound bridges, and information cuts.',practice:'Step 1: Find five examples of motivated cuts in a tutorial, vlog, or scene. Step 2: For each, identify the motivation: movement, gaze, sound, information, or attention. Step 3: Recreate those five cuts with different footage. Step 4: Build a 30-45s sequence where every cut has a written reason. Step 5: Remove one cut at a time and test whether it improves or weakens the flow. Output: five recreation drills + final sequence. Pass: no cut remains only because it looks cool',build:'A 30-second sequence where every cut has a reason.',criteria:'No random cuts.',resources:[k('Cuts & Transitions 101 — RocketJump Film School','https://www.youtube.com/watch?v=OAH0MoAv2CI','Watch'),k('Editing Problems I See in Every Short Film','https://www.youtube.com/watch?v=HWLEQ-oRuqs','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'s3',title:'J-cuts and L-cuts',tag:'Craft',why:'Audio can connect scenes before or after the visual cut.',learn:'Understand J-cut, L-cut, dialogue overlap, and sound bridges.',practice:'Step 1: Record or collect three dialogue exchanges. Step 2: Make three J-cuts where the next speaker/audio begins before the picture changes. Step 3: Make three L-cuts where audio continues after the picture changes. Step 4: Add one sound bridge between two different locations. Step 5: Listen with eyes closed to check whether the audio flow feels natural. Output: six J/L examples + 45-60s conversation edit. Pass: the scene feels connected even when picture and sound change at different times.',build:'Edit a 45-second conversation using both.',criteria:'Audio transitions feel intentional.',resources:[k('J-Cuts and L-Cuts — Adobe guide','https://helpx.adobe.com/ie/premiere/desktop/edit-projects/trim-clips/perform-j-cuts-and-l-cuts.html','Read'),k('How To Edit Talking Head Videos — The Editing Podcast','https://www.youtube.com/watch?v=7hHyY2HhHf4','Watch'),k('J-Cut vs L-Cut — Vimeo guide','https://vimeo.com/blog/post/guide-to-film-cuts','Read')]},
{id:'s4',title:'B-roll as storytelling',tag:'Craft',why:'B-roll should add information, emotion, or context—not hide bad cuts.',learn:'Match B-roll to words, ideas, movement, and emotion.',practice:'Step 1: Use 30-60s of talking-head footage. Step 2: Transcribe or summarize the key statements. Step 3: Collect 6-10 B-roll shots that add context, evidence, emotion, or visual variety. Step 4: Cover selected dialogue sections with B-roll without covering important words unnecessarily. Step 5: Remove any B-roll shot that adds no new information. Output: B-roll map + 60s segment. Pass: each B-roll shot has a clear reason tied to the spoken content.',build:'A 60-second B-roll-driven segment.',criteria:'Every B-roll shot adds something.',resources:[k('How to Edit Your Talking Head Videos — Denz Creates','https://www.youtube.com/watch?v=6JcrJzLOe-g','Watch'),k('How to Add B-Roll to a Talking-Head Video','https://viznow.ai/guides/how-to-add-b-roll-to-talking-head-video','Read'),k('How I Edit Smooth Transitions! — Daniel Schiffer','https://www.youtube.com/watch?v=5hJOdQ1zhX8','Watch')]},
{id:'s5',title:'Montage',tag:'Story',why:'Montage compresses time and creates meaning through juxtaposition.',learn:'Study repetition, contrast, progression, and compression.',practice:'Step 1: Collect 2 minutes of footage showing a process, place, or repeated action. Step 2: Choose one idea the montage should communicate. Step 3: Select only the strongest 8-15 shots. Step 4: Arrange them to create repetition, contrast, progression, or compression. Step 5: Add music only after the visual order works. Output: 20-30s montage + one-sentence intended meaning. Pass: the sequence communicates an idea that is stronger than any single shot.',build:'A 30-second montage with music and purposeful progression.',criteria:'The montage communicates a clear idea.',resources:[k('How to Cut a Film — The Secrets of Editing','https://www.youtube.com/watch?v=ORK8k8_mHyk','Watch'),k('The Kuleshov Effect — Folding Ideas','https://www.youtube.com/watch?v=Vy2Vhnqtu8I','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'s6',title:'Emotional rhythm',tag:'Psychology',why:'Emotion changes when you change timing, reaction, sound, and shot order.',learn:'Study anticipation, release, silence, reaction, and contrast.',practice:'Step 1: Pick one 15-25s moment. Step 2: Make a funny version by changing shot order, reaction timing, and sound accents. Step 3: Make a tense version by delaying information and using silence/holds. Step 4: Make an emotional version using reaction shots, slower timing, and restrained sound. Step 5: Keep the underlying footage mostly identical. Output: three versions. Pass: a viewer reports noticeably different emotional responses without being told what changed.',build:'Three versions of one 20-second scene.',criteria:'You can control emotional interpretation through editing.',resources:[k('Why action movies are boring... and spectacular','https://www.youtube.com/watch?v=f4yiwQakF7c','Watch'),k('Martin Scorsese — The Art of Silence','https://www.youtube.com/watch?v=NUrTRjEXjSM','Watch'),k('The Science of Film Editing','https://www.youtube.com/watch?v=02JF19lJ29M','Watch')]},]},
{id:'audio',title:'03 · Audio',subtitle:'Make the edit feel professional through sound',lessons:[
{id:'a1',title:'Dialogue fundamentals',tag:'Audio',why:'Bad dialogue audio can destroy otherwise good video.',learn:'Learn levels, clipping, noise, EQ basics, and consistency.',practice:'Step 1: Import one 30-60s dialogue clip. Step 2: Listen for clipping, background noise, inconsistent volume, and distracting frequencies. Step 3: Set usable dialogue gain without clipping. Step 4: Apply only the minimum cleanup needed, then test EQ gently. Step 5: Compare before/after at the same listening volume. Output: cleaned dialogue + 3-5 notes on changes. Pass: every word is easy to understand and no section feels dramatically louder or distorted.',build:'A 60-second dialogue edit with consistent volume.',criteria:'Speech is clear and comfortable.',resources:[k('How to SOUND DESIGN a Video — Step-By-Step Tutorial','https://www.youtube.com/watch?v=Wcxw3BPSt3A','Watch'),k('Editing Audio Volume with Keyframes — Kdenlive','https://docs.kdenlive.org/en/tips_and_tricks/how-tos/edit_audio_volume_with_keyframes.html','Read'),k('Kdenlive Audio Effects','https://docs.kdenlive.org/en/effects_and_filters/audio_effects.html','Read')]},
{id:'a2',title:'Room tone',tag:'Audio',why:'Room tone prevents cuts from sounding like audio gaps.',learn:'Capture and use consistent ambient sound.',practice:'Step 1: Record 10-20s of room tone in the same location as the dialogue. Step 2: Make three dialogue cuts with obvious background changes. Step 3: Place the room tone underneath and crossfade as needed. Step 4: Listen with headphones with eyes closed and note where a cut is audible. Step 5: Adjust the ambience until cuts disappear. Output: seamless 30-45s conversation. Pass: the listener cannot detect the dialogue cuts from abrupt changes in background sound.',build:'A seamless conversation scene.',criteria:'Dialogue cuts do not expose silence.',resources:[k('How To Edit Talking Head Videos — The Editing Podcast','https://www.youtube.com/watch?v=7hHyY2HhHf4','Watch'),k('Kdenlive audio workflow','https://docs.kdenlive.org/en/effects_and_filters/audio_effects.html','Read'),k('Kdenlive How-Tos','https://docs.kdenlive.org/en/tips_and_tricks/how-tos/index.html','Read')]},
{id:'a3',title:'Music as structure',tag:'Audio',why:'Music can control expectation and energy.',learn:'Use intro, build, drop, accent, and ending intentionally.',practice:'Step 1: Choose one 30-45s visual sequence and three different music tracks. Step 2: Mark each track’s intro, build, drop, accent, and ending. Step 3: Cut version A to the first track’s structure. Step 4: Repeat with the other two tracks, changing shot timing rather than forcing every beat. Step 5: Compare which version best supports the story. Output: three music-driven edits + a short comparison. Pass: the music changes the perceived energy while the visuals still make sense.',build:'A 45-second edit where music controls pacing.',criteria:'Cuts respond to musical structure without becoming predictable.',resources:[k('The Smart Way to Edit to the Beat of Music — Premiere Gal','https://www.youtube.com/watch?v=yU3U6TdV5Hw','Watch'),k('How to Edit to the Beat in DaVinci Resolve — Jason Yadlovski','https://www.jasonyadlovski.com/blog/2022/7/18/how-to-edit-to-the-beat-in-davinci-resolve-18-using-transients','Read')]},
{id:'a4',title:'Sound effects',tag:'Audio',why:'Small sounds create realism and emphasis.',learn:'Use whooshes, impacts, ambience, foley, and UI sounds sparingly.',practice:'Step 1: Start with a 20-30s sequence and mute its original effects where practical. Step 2: Add five useful sounds: ambience, one action sound, one impact, one transition accent, and one foley detail. Step 3: Place each effect precisely against an action. Step 4: Lower every effect until it supports rather than dominates. Step 5: Toggle all effects off/on to judge their contribution. Output: before/after sound-design version. Pass: removing the effects makes the scene noticeably less believable or impactful, while the effects never distract.',build:'A 30-second sound-designed edit.',criteria:'Effects support the story instead of distracting.',resources:[k('How to SOUND DESIGN a Video — Step-By-Step Tutorial','https://www.youtube.com/watch?v=Wcxw3BPSt3A','Watch'),k('The Power of Sound Effects — Bruin Creators','https://bruincreators.wixsite.com/home/ourcontent','Read'),k('Kdenlive Audio Effects','https://docs.kdenlive.org/en/effects_and_filters/audio_effects.html','Read')]},
{id:'a5',title:'Silence',tag:'Audio',why:'Silence creates contrast and gives important moments weight.',learn:'Use silence as a deliberate editing tool.',practice:'Step 1: Choose a 20-30s dramatic or informational sequence with music. Step 2: Identify the moment that should receive the most attention. Step 3: Remove music and unnecessary ambience for 1-3 seconds before that moment. Step 4: Reintroduce sound after the important moment. Step 5: Make a second version with no silence and compare them. Output: two versions + note on emotional difference. Pass: the silence creates a clear change in anticipation or emphasis rather than feeling like an accidental mute.',build:'A 30-second dramatic sequence with controlled silence.',criteria:'Silence feels intentional.',resources:[k('Martin Scorsese — The Art of Silence','https://www.youtube.com/watch?v=NUrTRjEXjSM','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'a6',title:'Mixing',tag:'Audio',why:'A professional mix makes dialogue, music, and effects coexist.',learn:'Learn gain staging, ducking, fades, and basic balance.',practice:'Step 1: Build a 45-60s scene containing dialogue, music, and at least three effects. Step 2: Set dialogue first so it is consistently intelligible. Step 3: Bring music underneath and lower it where speech needs space. Step 4: Balance effects so important actions are heard without competing with speech. Step 5: Add short fades and check the beginning/end for clicks or abrupt starts. Output: final mixed scene + before/after comparison. Pass: dialogue remains clear at normal listening volume while music and effects are still audible.',build:'A 60-second polished mix.',criteria:'Dialogue remains understandable over music.',resources:[k('How to SOUND DESIGN a Video — Step-By-Step Tutorial','https://www.youtube.com/watch?v=Wcxw3BPSt3A','Watch'),k('Editing Audio Volume with Keyframes — Kdenlive','https://docs.kdenlive.org/en/tips_and_tricks/how-tos/edit_audio_volume_with_keyframes.html','Read'),k('Kdenlive Audio Mixer','https://docs.kdenlive.org/en/user_interface/audio_mixer.html','Read')]},]},
{id:'visual',title:'04 · Visual Language',subtitle:'Color, motion, composition, and visual continuity',lessons:[
{id:'v1',title:'Composition for editors',tag:'Visual',why:'Editors inherit composition decisions and can reinforce them through timing and cropping.',learn:'Study framing, leading lines, negative space, balance, and visual hierarchy.',practice:'Step 1: Capture or collect 20 frames from videos you consider visually strong. Step 2: For each frame, mark subject, negative space, leading lines, balance, and visual hierarchy. Step 3: Choose five frames and explain where the eye goes first. Step 4: Build a short sequence whose shot order preserves a clear visual hierarchy. Step 5: Crop/reframe one weak shot to improve composition. Output: 20-frame analysis + 20-30s sequence. Pass: you can explain why the viewer should look at the intended subject in each key shot.',build:'A sequence where every shot has deliberate framing.',criteria:'You can explain the visual hierarchy.',resources:[k('Joel & Ethan Coen — Shot | Reverse Shot','https://www.youtube.com/watch?v=5UE3jz_O_EM','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'v2',title:'Color correction',tag:'Color',why:'Correction makes footage consistent before style is added.',learn:'Exposure, white balance, contrast, saturation, skin tones.',practice:'Step 1: Collect three shots from different takes/locations that do not match. Step 2: Compare exposure, white balance, contrast, saturation, and skin tones. Step 3: Correct exposure and white balance first. Step 4: Match contrast and saturation second. Step 5: Toggle before/after and check the shots in sequence. Output: three matched shots + correction notes. Pass: the sequence feels like one scene rather than three unrelated clips.',build:'A corrected 30-second sequence.',criteria:'Shots look like they belong together.',resources:[k('How to color correct a video in KDENLIVE','https://www.youtube.com/watch?v=h-KslQl0Lx0','Watch'),k('Color and Image Correction — Kdenlive','https://docs.kdenlive.org/en/effects_and_filters/video_effects/color_image_correction.html','Read')]},
{id:'v3',title:'Color grading',tag:'Color',why:'A grade supports mood after technical correction.',learn:'Separate correction from creative look.',practice:'Step 1: First create a technically corrected neutral version. Step 2: Duplicate it into warm, cool, and neutral looks. Step 3: Change only a small set of grading controls in each version. Step 4: Watch each with the same soundtrack and decide what mood it suggests. Step 5: Choose the grade that best serves the story and write why. Output: three looks + final selected grade. Pass: the creative look is intentional and does not hide obvious exposure or white-balance problems.',build:'A 30-second stylized sequence.',criteria:'The look supports the story.',resources:[k('Kdenlive Tutorial for Beginners — Kevin Stratvert','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Color and Image Correction — Kdenlive','https://docs.kdenlive.org/en/effects_and_filters/video_effects/color_image_correction.html','Read')]},
{id:'v4',title:'Speed and time',tag:'Motion',why:'Speed changes emphasis and perceived energy.',learn:'Understand slow motion, speed ramps, freeze frames, and time compression.',practice:'Step 1: Choose a 20-30s sequence containing movement or a key action. Step 2: Make version A with normal speed. Step 3: Make version B with one motivated slow-motion moment. Step 4: Make version C with a speed ramp or freeze frame around the key beat. Step 5: Remove any speed change that feels decorative rather than useful. Output: three versions. Pass: every change in speed clearly improves emphasis, timing, or energy.',build:'A 30-second dynamic sequence.',criteria:'Speed changes are motivated.',resources:[k('How I Edit Smooth Transitions! — Daniel Schiffer','https://www.youtube.com/watch?v=5hJOdQ1zhX8','Watch'),k('Kdenlive Effects and Filters','https://docs.kdenlive.org/en/effects_and_filters.html','Read')]},
{id:'v5',title:'Motion and keyframes',tag:'Motion',why:'Keyframes create controlled movement and emphasis.',learn:'Position, scale, opacity, and smooth animation.',practice:'Step 1: Create one 20-30s sequence with a subject that needs emphasis. Step 2: Animate scale on one shot. Step 3: Animate position/pan on another. Step 4: Animate opacity or another supported property on a third. Step 5: Adjust keyframe spacing and easing/smoothing so movement starts and stops naturally. Output: three animation drills + combined sequence. Pass: no movement looks abrupt unless that abruptness is intentional.',build:'A 20-second motion sequence.',criteria:'Motion starts/stops naturally.',resources:[k('Kdenlive Quick Start — keyframe section','https://userbase.kde.org/Kdenlive/Manual/QuickStart','Read'),k('Smooth Keyframe Interpolation — Kdenlive','https://docs.kdenlive.org/en/tips_and_tricks/useful_info/smooth_keyframe_interpolation.html','Read'),k('How I Edit Smooth Transitions! — Daniel Schiffer','https://www.youtube.com/watch?v=5hJOdQ1zhX8','Watch')]},
{id:'v6',title:'Visual continuity',tag:'Craft',why:'Color, motion, screen direction, and composition should not accidentally fight each other.',learn:'Match direction, brightness, color, lens feel, and movement.',practice:'Step 1: Assemble 6-8 shots with deliberate continuity. Step 2: Introduce five controlled problems such as direction mismatch, brightness mismatch, color mismatch, movement mismatch, or inconsistent framing. Step 3: Fix each problem using shot order, trimming, reframing, color adjustment, or replacement. Step 4: Watch the final sequence once without stopping. Output: before/after sequence + five corrections list. Pass: visual changes no longer pull attention away from the story.',build:'A seamless multi-shot sequence.',criteria:'Visual changes feel intentional.',resources:[k('Cuts & Transitions 101 — RocketJump Film School','https://www.youtube.com/watch?v=OAH0MoAv2CI','Watch'),k('How to Cut a Film — CineFix','https://www.youtube.com/watch?v=ORK8k8_mHyk','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},]},
{id:'kdenlive',title:'05 · Kdenlive',subtitle:'Turn editing knowledge into repeatable software skill',lessons:[
{id:'k1',title:'Project setup',tag:'Kdenlive',why:'Correct project settings prevent technical problems later.',learn:'Project folders, profiles, frame rate, resolution, and assets.',practice:'Step 1: Create a dedicated project folder with subfolders for footage, audio, graphics, project files, exports, and archive. Step 2: Choose a sensible project profile based on the target footage. Step 3: Import and organize assets with clear names/bins. Step 4: Save a template project with your preferred tracks and basic settings. Step 5: Close and reopen it to verify everything is intact. Output: reusable project template + folder structure. Pass: a new project can be started without guessing where files belong or what settings to choose.',build:'A reusable project template.',criteria:'You can start a project without guessing settings.',resources:[k('Learn Kdenlive in 30 Minutes — Nuxttux Creative Studio','https://www.youtube.com/watch?v=zYD0b8LpiQA','Watch'),k('Kdenlive Tutorial for Beginners — Kevin Stratvert','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Project Settings','https://docs.kdenlive.org/en/project_and_asset_management/project_settings.html','Read')]},
{id:'k2',title:'Timeline mastery',tag:'Kdenlive',why:'Timeline fluency is where editing speed comes from.',learn:'Selection, razor, spacer, ripple, tracks, snapping, and keyboard workflow.',practice:'Step 1: Import enough footage for a 60s edit. Step 2: Practice selection, razor, snapping, track targeting, and spacer/ripple operations separately for 5 minutes each. Step 3: Edit the sequence once using the mouse normally. Step 4: Repeat while using keyboard shortcuts for the most common cuts and navigation. Step 5: Note three actions that became faster. Output: rough cut + personal shortcut list. Pass: you can move, trim, cut, and rearrange without repeatedly hunting through menus.',build:'A fast rough cut.',criteria:'You can navigate and cut confidently.',resources:[k('Kdenlive Tutorial for Beginners — timeline editing','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Advanced Tutorial — Wasz Informatyk','https://www.youtube.com/watch?v=BcdcfDkSOiE','Watch'),k('Kdenlive Editing','https://docs.kdenlive.org/en/cutting_and_assembling/editing.html','Read'),k('Kdenlive Keyboard Shortcuts','https://docs.kdenlive.org/en/user_interface/shortcuts.html','Read')]},
{id:'k3',title:'Transitions and compositions',tag:'Kdenlive',why:'Transitions should solve a visual problem or create a deliberate feeling.',learn:'Mixes, dissolves, wipes, compositions, and when not to use them.',practice:'Step 1: Create three adjacent shot pairs where a transition could be used. Step 2: Recreate a simple mix/dissolve, a wipe, and one composition-based transition. Step 3: Make a second pass and remove every transition that does not solve a clear problem. Step 4: Compare the versions. Step 5: Write the intended purpose of each remaining transition. Output: 30s transition study + before/after. Pass: every transition has a reason tied to story, time, space, or style.',build:'A 30-second transition study.',criteria:'You choose transitions intentionally.',resources:[k('Kdenlive Tutorial for Beginners — transitions','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Adding Transitions — Nuxttux Creative Studio','https://www.skillshare.com/en/classes/kdenlive-essentials-cut-edit-and-enhance-videos-fast/374088550','Read'),k('Kdenlive Transitions','https://docs.kdenlive.org/en/compositing/transitions.html','Read')]},
{id:'k4',title:'Masks and blending',tag:'Kdenlive',why:'Compositing expands what simple cuts can do.',learn:'Alpha, masks, blending, and selective effects.',practice:'Step 1: Choose a simple shot with one object to isolate. Step 2: Duplicate the clip and create a mask around the object. Step 3: Animate the mask for movement if necessary. Step 4: Blend the isolated area over another background/shot. Step 5: Inspect edges frame by frame and fix obvious leaks. Output: 10-20s masked composite. Pass: the object remains controlled throughout the shot without distracting edges or timing errors.',build:'A simple masked composite.',criteria:'Mask edges and timing are controlled.',resources:[k('Object Mask — Nuxttux Creative Studio','https://www.youtube.com/watch?v=4Pw9b6xhO_k','Watch'),k('Remove Green Screen — Nuxttux Creative Studio','https://www.youtube.com/watch?v=cGNC7TBk_SY','Watch'),k('Kdenlive Masking','https://docs.kdenlive.org/en/compositing/masking_and_tracking/masking.html','Read')]},
{id:'k5',title:'Titles and subtitles',tag:'Kdenlive',why:'Readable graphics improve communication.',learn:'Hierarchy, safe areas, timing, subtitles, and lower thirds.',practice:'Step 1: Create one lower third with name and role. Step 2: Create one subtitle style and test it on three different sentences. Step 3: Check readable size, contrast, safe placement, timing, and line length. Step 4: Save/reuse the style for a second clip. Step 5: Export a 20-30s sample showing both elements. Output: reusable lower third + subtitle style. Pass: text is readable on desktop and mobile-sized viewing and remains visually consistent.',build:'A branded title package.',criteria:'Text is readable and consistent.',resources:[k('How to add text to video — Nuxttux Creative Studio','https://www.youtube.com/watch?v=9PTqvcRobUw','Watch'),k('Kdenlive Tutorial for Beginners — titles','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Title Clips','https://docs.kdenlive.org/en/titles_and_graphics/titles/titles.html','Read'),k('Kdenlive Subtitles','https://docs.kdenlive.org/en/effects_and_filters/subtitles.html','Read')]},
{id:'k6',title:'Effects discipline',tag:'Kdenlive',why:'Professional editing is not effect stacking.',learn:'Choose effects based on story, polish, and problem solving.',practice:'Step 1: Pick a 20-30s clip that can be polished with a few effects. Step 2: Create an intentionally overdone version with several effects. Step 3: Duplicate it and remove half or more of the effects. Step 4: For every remaining effect, write the problem it solves or the creative reason for it. Step 5: Compare both versions at normal playback speed. Output: overdone vs restrained edit + effect justification. Pass: the restrained version looks cleaner and every remaining effect has a clear purpose.',build:'A restrained polished edit.',criteria:'Every effect has a reason.',resources:[k('Keyframe Interpolation — Nuxttux Creative Studio','https://www.youtube.com/watch?v=F1h6Kg-WLDE','Watch'),k('Video Noise Reduction — Nuxttux Creative Studio','https://www.youtube.com/watch?v=dQNe1Dju3qs','Watch'),k('Kdenlive Effects and Filters','https://docs.kdenlive.org/en/effects_and_filters.html','Read')]},
{id:'k7',title:'Proxy workflow for low-end PCs',tag:'Performance',why:'Your Toshiba needs an editing workflow designed around its limits.',learn:'Proxy clips, preview rendering, and lightweight project settings.',practice:'Step 1: Create a small 1080p project using footage that causes your PC to struggle. Step 2: Enable proxy clips and choose a practical proxy setting. Step 3: Compare timeline playback before and after proxies. Step 4: Test scrubbing, trimming, and basic effects while proxies are active. Step 5: Render a short section and verify that the final uses the original-quality source. Output: proxy-enabled project + short performance notes. Pass: editing becomes materially more responsive without changing the final delivery quality.',build:'A 1080p project that remains workable on your PC.',criteria:'You can edit without constant playback frustration.',resources:[k('Kdenlive — How to Use Proxy and Make Editing Much Faster','https://www.youtube.com/watch?v=h-wD7Qk0qmY','Watch'),k('Kdenlive Advanced Tutorial — proxies on older computers','https://www.youtube.com/watch?v=BcdcfDkSOiE','Watch'),k('Kdenlive Proxy Clips','https://docs.kdenlive.org/en/getting_started/configure_kdenlive/configuration_proxy_clips.html','Read')]},
{id:'k8',title:'Export and delivery',tag:'Kdenlive',why:'A great edit still fails if the final file is wrong.',learn:'Codecs, containers, resolution, frame rate, bitrate, and platform exports.',practice:'Step 1: Take one finished sequence and define its delivery target. Step 2: Export a full-quality master using appropriate resolution, frame rate, codec, and container. Step 3: Export a second version for a vertical/social target. Step 4: Inspect both files for audio sync, frame rate, black frames, cropping, and playback. Step 5: Place final files in a delivery folder with clear names and version numbers. Output: master + social export + delivery folder. Pass: both files play correctly and match the requested platform format.',build:'A delivery folder with clean filenames.',criteria:'You can deliver platform-ready files without guessing.',resources:[k('Kdenlive How To Render — Mufasu CAD','https://www.youtube.com/watch?v=ZOoVvfr7SPM','Watch'),k('Kdenlive Tutorial for Beginners — export','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Rendering','https://docs.kdenlive.org/en/exporting/render.html','Read')]},]},
{id:'projects',title:'06 · Project Lab',subtitle:'Projects are the proof that the skills are real',lessons:[
{id:'p1',title:'Project 01 — Cinematic 30s',tag:'Project',why:'A short project forces you to practice shot choice and rhythm.',learn:'Review pacing, motivated cuts, music, and color.',practice:'Step 1: Gather 10-20 clips around one subject or action. Step 2: Create selects before placing clips on the final timeline. Step 3: Build a 30s story with a clear opening image, progression, and ending. Step 4: Add music only after the visual rhythm works. Step 5: Perform a correction pass, then a restrained grade and audio polish pass. Output: final 30s cinematic edit + three strongest rejected shots. Pass: the opening creates interest, every cut feels intentional, audio is controlled, and the visual treatment is coherent.',build:'A polished 30-second cinematic sequence.',criteria:'Strong opening, intentional cuts, controlled audio, coherent grade.',resources:[k('The Art of Editing — This Guy Edits','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('How to Edit Cinematic Videos — Film Editing Basics','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive color correction','https://docs.kdenlive.org/en/effects_and_filters/video_effects/color_image_correction.html','Read')]},
{id:'p2',title:'Project 02 — Talking-head YouTube',tag:'Project',why:'Talking-head editing is a practical freelance skill.',learn:'Dialogue cleanup, jump cuts, B-roll, captions, and pacing.',practice:'Step 1: Choose or record 5-10 minutes of talking-head material. Step 2: Create a transcript/notes and mark the strongest statements. Step 3: Build a dialogue-only rough cut before adding B-roll or graphics. Step 4: Add purposeful B-roll, captions, music, and simple transitions. Step 5: Watch once as a viewer and remove anything that slows the message. Output: 3-5 minute YouTube segment. Pass: the message is easy to follow, speech is clean, B-roll adds information, and the edit never feels busy without purpose.',build:'A 3–5 minute YouTube segment.',criteria:'Clear story, clean audio, purposeful B-roll.',resources:[k('How to Edit Your Talking Head Videos — Denz Creates','https://www.youtube.com/watch?v=6JcrJzLOe-g','Watch'),k('How To Edit Tutorial Videos (Step by Step Guide) — Jonny Shapland','https://www.youtube.com/watch?v=9sEgdyh1Qvo','Watch'),k('Add subtitles & captions — YouTube Help','https://support.google.com/youtube/answer/2734796','Read')]},
{id:'p3',title:'Project 03 — Tech tutorial',tag:'Project',why:'This connects editing with your tech interests and future channel.',learn:'Screen recordings, callouts, zooms, cursor emphasis, and voiceover.',practice:'Step 1: Pick one technical task to explain. Step 2: Outline the steps before editing. Step 3: Record or collect the screen demonstration and supporting voiceover. Step 4: Edit for clarity, adding zooms/callouts only where they help the viewer locate something. Step 5: Check every instruction against the final video. Output: 4-6 minute tutorial. Pass: a viewer can perform the demonstrated task without needing extra explanation.',build:'A 4–6 minute tech tutorial.',criteria:'Viewer can follow every step.',resources:[k('How To Edit Tutorial Videos (Step by Step Guide) — Jonny Shapland','https://www.youtube.com/watch?v=9sEgdyh1Qvo','Watch'),k('Screen Recording Basics — Editing In-Depth — TechSmith','https://www.classcentral.com/course/youtube-screen-recording-basics-6-editing-in-depth-56932','Read'),k('How to Edit a Screen Recording or Tutorial Video — Adobe Video World','https://adobevideoworld.com/edit-screen-recording-video/','Read')]},
{id:'p4',title:'Project 04 — Short-form pack',tag:'Project',why:'Short-form work teaches fast hooks and retention.',learn:'Hooks, pattern interrupts, captions, pacing, and vertical delivery.',practice:'Step 1: Start with one source video or topic. Step 2: Write three different hooks that promise a clear benefit or curiosity gap. Step 3: Build three 20-30s openings with different pacing/pattern interruption. Step 4: Give each a clear payoff and remove unnecessary setup. Step 5: View all three on a phone-sized player and choose the strongest. Output: three short-form edits. Pass: each video communicates its premise in the opening seconds and delivers the promised payoff.',build:'Three short-form videos from one source.',criteria:'Each has a clear hook and payoff.',resources:[k('Editing Hacks YouTubers Use to Hook You — Film Booth','https://www.youtube.com/watch?v=sZ4t7fJXnT0','Watch'),k('How to Edit Your Talking Head Videos — Denz Creates','https://www.youtube.com/watch?v=6JcrJzLOe-g','Watch'),k('Add subtitles & captions — YouTube Help','https://support.google.com/youtube/answer/2734796','Read')]},
{id:'p5',title:'Project 05 — Product promo',tag:'Project',why:'Commercial-style editing develops visual polish and client value.',learn:'Product shots, rhythm, typography, sound design, and CTA.',practice:'Step 1: Choose one simple product/object and define one selling point. Step 2: Collect close, wide, detail, and action shots. Step 3: Build a 15s visual rhythm around the product benefit. Step 4: Add restrained typography, sound design, and a clear CTA. Step 5: Make a second version with a different opening and compare which sells the idea faster. Output: 30-45s promo + alternate opening. Pass: the product and its main value are obvious without narration.',build:'A 30–45 second promo.',criteria:'Clear product value and polished presentation.',resources:[k('HOW I FILM HANDHELD ICE CREAM B ROLL — Daniel Schiffer','https://www.youtube.com/watch?v=AKxwO8z8ptM','Watch'),k('How I Edit Smooth Transitions! — Daniel Schiffer','https://www.youtube.com/watch?v=5hJOdQ1zhX8','Watch'),k('Product Video Editing guide','https://fstoppers.com/video-editing/how-make-product-video-shot-tripod-more-dynamic-580985','Read')]},
{id:'p6',title:'Project 06 — Mini documentary',tag:'Project',why:'Documentary editing tests story judgment with imperfect footage.',learn:'Interview structure, B-roll, narration, archival material, and pacing.',practice:'Step 1: Choose a person, place, process, or small local story. Step 2: Conduct/collect an interview and supporting B-roll. Step 3: Write a paper edit: what must the viewer know, feel, and discover? Step 4: Build the story from strongest interview moments, then cover gaps with B-roll and natural sound. Step 5: Remove anything interesting that does not serve the central story. Output: 3-5 minute mini documentary. Pass: the story has a clear subject, progression, and ending without needing live explanation from the editor.',build:'A 3–5 minute mini documentary.',criteria:'The story works without explaining it verbally.',resources:[k('The Truth about Reality TV and Documentary Editing — This Guy Edits','https://www.youtube.com/watch?v=VBCSWWX5Dt4','Watch'),k('The Lies of Non-Fiction Editing — This Guy Edits','https://thisguyedits.com/','Read'),k('Documentary Editing — This Guy Edits','https://thisguyedits.com/category/documentary-editing/','Read')]},]},
{id:'pro',title:'07 · Professional Workflow',subtitle:'Learn to work like an editor, not just use an editor',lessons:[
{id:'r1',title:'Read a brief',tag:'Pro',why:'Clients pay for outcomes, not software knowledge.',learn:'Extract audience, message, platform, tone, deadline, and deliverables.',practice:'Step 1: Use a fake client request such as "Turn this 8-minute interview into a 60s social video." Step 2: Extract audience, purpose, tone, platform, deadline, deliverables, references, and revision expectations. Step 3: Turn those into a one-page checklist. Step 4: List five questions that must be answered before editing begins. Step 5: Only after the brief is complete, outline the edit. Output: one completed edit brief. Pass: another editor could start the job using your brief without asking basic scope questions.',build:'A one-page edit brief.',criteria:'You can define the job before touching footage.',resources:[k('How Does an Editor Think and Feel? — This Guy Edits','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('5 Things Editors Literally Do — This Guy Edits','https://www.youtube.com/watch?v=QqIIHi5F3-o','Watch'),k('YouTube pre-production & brief guidance','https://help.youtube.com/nonprofits/resources/how-to-guide/get-your-nonprofit-on-youtube/','Read')]},
{id:'r2',title:'Selects before polish',tag:'Pro',why:'Professional speed comes from decisions before effects.',learn:'Organize footage, label selects, and build a paper/rough edit.',practice:'Step 1: Import 20 mixed clips into a practice project. Step 2: Watch everything once and rename/organize assets. Step 3: Mark strong takes, useful B-roll, and unusable clips. Step 4: Build a selects sequence containing only chosen material. Step 5: Create a rough story from selects without adding effects or polish. Output: organized bins + selects sequence + rough cut. Pass: the story is understandable before any graphics, transitions, or color work are added.',build:'A structured project bin + selects sequence.',criteria:'You know what the edit is before polishing.',resources:[k('5 Things Editors Literally Do — This Guy Edits','https://www.youtube.com/watch?v=QqIIHi5F3-o','Watch'),k('The Truth about Reality TV and Documentary Editing — This Guy Edits','https://www.youtube.com/watch?v=VBCSWWX5Dt4','Watch'),k('Kdenlive Quick Start','https://docs.kdenlive.org/en/getting_started/quickstart.html','Read')]},
{id:'r3',title:'Rough cut → fine cut',tag:'Pro',why:'Trying to perfect every shot immediately wastes time.',learn:'Separate story, pacing, polish, graphics, and final QC passes.',practice:'Step 1: Make a story-first rough cut with dialogue/visual essentials only. Step 2: Do a pacing pass focused only on timing and shot order. Step 3: Do a polish pass for audio, color, graphics, and transitions. Step 4: Export a review version and write five possible notes. Step 5: Compare rough, fine, and final to see how each pass solved a different problem. Output: three labeled versions. Pass: each version has a clearly different purpose and the final is not built by polishing unfinished story decisions.',build:'Rough, fine, and final versions of one project.',criteria:'Each pass has a different purpose.',resources:[k('Editing Problems I See in Every Short Film — This Guy Edits','https://www.youtube.com/watch?v=HWLEQ-oRuqs','Watch'),k('The Art of Editing — This Guy Edits','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'r4',title:'Revision workflow',tag:'Pro',why:'Client revisions are normal; chaos is optional.',learn:'Versioning, notes, timecodes, scope, and change tracking.',practice:'Step 1: Create a mock client delivery and write 10 revision notes with timecodes. Step 2: Group notes into story, pacing, audio, graphics, and technical categories. Step 3: Apply one category at a time and save a new version after a meaningful round. Step 4: Verify that fixes in one area did not break another. Step 5: Record what changed in a simple revision log. Output: v1, v2, v3 plus revision log. Pass: every client note is traceable to a change and no requested change is accidentally lost.',build:'A versioned delivery workflow.',criteria:'You can revise without breaking the project.',resources:[k('How to handle client revisions — The Futur','https://www.youtube.com/watch?v=uSma86sakPw','Watch'),k('The Perfect Video Revision Workflow','https://yuktis.com/blog/video-revision-workflow-eliminating-feedback-loops','Read'),k('Video editing client workflow tips','https://www.youtube.com/watch?v=QqIIHi5F3-o','Watch')]},
{id:'r5',title:'Portfolio reel',tag:'Pro',why:'A portfolio should demonstrate outcomes quickly.',learn:'Select only work that represents your target service.',practice:'Step 1: Pick only 3-5 strongest pieces that match the type of editing you want to sell. Step 2: Put the strongest evidence in the first 10 seconds. Step 3: Remove filler, long intros, logos, and unrelated work. Step 4: Add simple labels only where context is necessary. Step 5: Watch on desktop and phone and cut anything that drags. Output: 30-45s reel + project links/list. Pass: a stranger can identify the service, quality level, and strongest work within 10 seconds.',build:'Your first editing portfolio page/reel.',criteria:'A stranger understands what you can edit within 10 seconds.',resources:[k('How to Build a Great Portfolio as a Freelance Video Editor — veeveK','https://www.youtube.com/watch?v=BH-tqM9B0SA','Watch'),k('How to Build a Great Portfolio as a Freelance Video Editor — Abhay PS Rajawat','https://www.youtube.com/watch?v=KWSNOTWIOJI','Watch'),k('This Guy Edits — Portfolio & career examples','https://thisguyedits.com/','Read')]},
{id:'r6',title:'Delivery checklist',tag:'Pro',why:'Reliability is a professional skill.',learn:'Check audio, black frames, spelling, captions, exports, filenames, and backups.',practice:'Step 1: Create a checklist covering picture, sound, captions, spelling, timing, black frames, export settings, filenames, and backup. Step 2: Watch the final project once continuously. Step 3: Watch again with headphones focused only on audio. Step 4: Scrub frame-by-frame around cuts, titles, and transitions. Step 5: Play the exported file outside Kdenlive and compare it to the timeline. Output: signed-off QC checklist. Pass: no obvious technical or spelling issue remains in the delivered file.',build:'Reusable delivery checklist.',criteria:'You catch technical mistakes before delivery.',resources:[k('Kdenlive Tutorial for Beginners — Kevin Stratvert','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Exporting','https://docs.kdenlive.org/en/exporting.html','Read'),k('YouTube supported video formats','https://support.google.com/youtube/answer/4603579','Read')]},]},
{id:'money',title:'08 · Money Path',subtitle:'Turn editing ability into a small, repeatable service',lessons:[
{id:'m1',title:'Pick an offer',tag:'Money',why:'A clear service is easier to sell than “I edit videos.”',learn:'Choose one starting niche: shorts, YouTube, tech, podcasts, or promos.',practice:'Step 1: Choose one starting client type such as YouTube creators, tech channels, shorts creators, podcasts, or small businesses. Step 2: Write three service offers with a specific output, length, turnaround, and revision limit. Step 3: Compare which offer is easiest to produce repeatedly with current skills/equipment. Step 4: Choose one offer and write a one-sentence value proposition. Step 5: Test whether a stranger understands it without the phrase "I can edit videos." Output: one finalized starter offer. Pass: the offer names the client, deliverable, scope, and result clearly.',build:'One clear starter offer.',criteria:'A client understands what they receive.',resources:[k('How to Start Freelance Video Editing','https://adobevideoworld.com/start-freelance-video-editing/','Read'),k('How to Get Your First Video Editing Client in 2026 — Kam','https://www.youtube.com/watch?v=fKOARKHAt0U','Watch'),k('The truth about getting VIDEO EDITING CLIENTS — Brainstorm Tutoriais','https://www.youtube.com/watch?v=lHaYgS_16Vk','Watch')]},
{id:'m2',title:'Build a sample package',tag:'Money',why:'Samples prove your service before a client trusts you.',learn:'Package 3–5 relevant examples with before/after context.',practice:'Step 1: Select 3-5 pieces that match the chosen offer. Step 2: For each, create a short before/after or problem/result description. Step 3: Organize them in one clean folder/page with consistent naming. Step 4: Write a short service description explaining what is included and what is not. Step 5: Ask whether a prospect could judge the service without a live explanation. Output: mini portfolio package. Pass: the portfolio demonstrates the exact service being sold rather than unrelated editing skills.',build:'Starter portfolio + service description.',criteria:'A prospect can evaluate you without a long explanation.',resources:[k('How to Build a Great Portfolio as a Freelance Video Editor — veeveK','https://www.youtube.com/watch?v=BH-tqM9B0SA','Watch'),k('How to Build a Great Portfolio as a Freelance Video Editor — Abhay PS Rajawat','https://www.youtube.com/watch?v=KWSNOTWIOJI','Watch'),k('How to Get Your First Video Editing Client','https://www.gigxomi.com/blog/how-to-get-your-first-video-editing-client','Read')]},
{id:'m3',title:'Find prospects',tag:'Money',why:'Income comes from consistent outreach and useful relationships.',learn:'Identify creators, small businesses, tech channels, and local brands.',practice:'Step 1: Choose one prospect category and define what makes a good lead. Step 2: Find 20 realistic prospects using public profiles/platforms. Step 3: Record name, channel/business, contact route, current content, likely editing need, and status. Step 4: Prioritize the top five based on fit rather than follower count. Step 5: Write one personalized outreach angle for each. Output: 20-lead tracker + five personalized angles. Pass: every lead is realistic and has a specific reason the editing service could help.',build:'A simple outreach tracker.',criteria:'You have a repeatable prospecting process.',resources:[k('The truth about getting VIDEO EDITING CLIENTS — Brainstorm Tutoriais','https://www.youtube.com/watch?v=lHaYgS_16Vk','Watch'),k('How to ACTUALLY Get Your First Editing Client in 2026 — Kam','https://www.youtube.com/watch?v=fKOARKHAt0U','Watch'),k('How to Get Video Editing Clients — SignalsHunt','https://signalshunt.com/blog/how-to-get-video-editing-clients','Read')]},
{id:'m4',title:'Price scope, not hope',tag:'Money',why:'Clear scope prevents undercharging and endless revisions.',learn:'Define deliverables, turnaround, revisions, and extras.',practice:'Step 1: Choose a base service such as one short, one YouTube edit, or one promo. Step 2: Define exactly what footage length, finished length, captions, graphics, revisions, and turnaround are included. Step 3: Build three packages by changing scope—not by making vague promises. Step 4: Write what counts as an extra. Step 5: Review the packages as if you were a client and remove ambiguous wording. Output: one-page rate card. Pass: there is a clear boundary between included work and paid extras.',build:'A simple rate card.',criteria:'You can explain exactly what is included.',resources:[k('How to Price Your Video Editing Work','https://adobevideoworld.com/price-video-editing-work/','Read'),k('Video Editing Pricing Guide 2026','https://pixflow.net/blog/freelance-video-editing-rates/','Read'),k('How Much Does a Freelance Video Editor Cost? — 2026 Guide','https://hammadj.com/pricing-guide.html','Read')]},
{id:'m5',title:'Repeatability',tag:'Money',why:'A service becomes sustainable when your process gets faster.',learn:'Templates, presets, checklists, project organization, and reusable assets.',practice:'Step 1: Open one finished project and identify repeated actions. Step 2: Turn those actions into a template: folder structure, track layout, title styles, export presets, checklist, and commonly used effects. Step 3: Create the template and test it on a second small project. Step 4: Time how long project setup takes before and after. Step 5: Remove steps that do not provide value. Output: reusable project template + workflow checklist. Pass: the second project starts faster and follows the same reliable process.',build:'Your first repeatable editing system.',criteria:'The second project can start faster than the first.',resources:[k('Kdenlive Tutorial for Beginners — Kevin Stratvert','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Quick Start','https://docs.kdenlive.org/en/getting_started/quickstart.html','Read'),k('How to Get Video Editing Clients — Repeatable System','https://www.gigxomi.com/blog/how-to-get-video-editing-clients','Read')]},]},
]
export const allLessons=stages.flatMap(s=>s.lessons.map(l=>({...l,stageId:s.id,stageTitle:s.title})))
